mapper.insert:
INSERT INTO content (
     title
    ,body
    ,content_type
    ,visible_yn
    ,ordering
    ,content_link
    ,created_at
) VALUES

(
     IFNULL(#{item.safetyCateNm3}, '행동요령 참고 자료')
    ,#{item.body}
    ,#{contentType}
    ,'Y'
    ,#{item.ordering}
    ,#{item.contentsUrl}
    ,NOW()
)

mapper.select:
SELECT c.content_id ,c.title ,c.body ,c.content_type ,ci.code_item_name AS content_type_name ,cgi.code_group_id AS group_name ,REPLACE(c.content_link, 'http://mepv2.safekorea.go.kr', '') AS content_link ,c.ordering ,c.visible_yn FROM content c LEFT JOIN code_item ci ON c.content_type = ci.code_item_id LEFT JOIN code_group cgi ON ci.code_group_id = cgi.code_group_id
AND c.content_type = #{contentType}
AND c.visible_yn = #{visibleYn}
ORDER BY c.ordering ASC
